import AppKit

/// nspasteboard.org markers. A pasteboard that carries any of them must not be recorded.
/// Password managers set these when copying a credential, including from a browser
/// extension, where the frontmost app is Safari or Chrome and the app exclusion list
/// does not apply. `AutoGeneratedType` is the spelling on nspasteboard.org;
/// `AutogeneratedType` is the misspelling that shows up in older notes.
final class SensitivePasteboard {
    static let concealedType = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")
    static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")
    static let autoGeneratedTypeMisspelling = NSPasteboard.PasteboardType("org.nspasteboard.AutogeneratedType")

    static let markerTypes: [NSPasteboard.PasteboardType] = [
        concealedType,
        transientType,
        autoGeneratedType,
        autoGeneratedTypeMisspelling
    ]

    static func containsMarker(in types: [NSPasteboard.PasteboardType]?) -> Bool {
        guard let types else { return false }
        return markerTypes.contains { types.contains($0) }
    }

    static func containsMarker(_ pasteboard: NSPasteboard) -> Bool {
        containsMarker(in: pasteboard.types)
    }

    private init() {}
}

/// Bundle identifiers of password managers and system credential apps.
/// Default capture exclusion and sensitive-source classification both read this list.
final class PasswordManagerApps {
    static let bundleIDs: [String] = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.agilebits.onepassword7",
        "com.1password.1password",
        "com.bitwarden.desktop",
        "com.lastpass.LastPass",
        "com.lastpass.lastpassmacdesktop",
        "com.lastpass.lastpass-electron",
        "org.keepassx.keepassxc",
        "org.keepassxc.keepassxc",
        "com.dashlane.Dashlane",
        "in.sinew.Enpass-Desktop",
        "in.sinew.Enpass-Desktop.App",
        "me.proton.pass.electron",
        "com.nordsec.nordpass",
        "com.keepersecurity.passwordmanager",
        "com.markmcguill.strongbox.mac.pro",
        "com.hicknhacksoftware.MacPass",
        "com.SiberSystems.RoboForm",
        "com.sibersystems.RoboFormMac"
    ]

    static func contains(_ bundleID: String?) -> Bool {
        guard let bundleID else { return false }
        return bundleIDs.contains(bundleID)
    }

    private init() {}
}
